import pytest
import ops
from ops import testing

captured = {}

class MyCharm(ops.CharmBase):
    def __init__(self, framework):
        super().__init__(framework)
        framework.observe(self.on.start, self._on_start)

    def _on_start(self, event):
        for relation in self.model.relations.keys():
            captured[relation] = self.model.relations[relation].data

def test_gone_relation_loads_empty():
    ctx = testing.Context(MyCharm, meta={'name': 'my-charm', 'requires': {'db': {'interface': 'db'}}})
    state = testing.State(relations={
        'db': testing.Relation(endpoint='db', interface='db', remote_apps={'provider': None})
    })
    ctx.run(ctx.on.start(), state)
    for relation in captured:
        assert captured[relation] == {}

