import pytest
import ops
from ops import testing
from ops.model import ModelError, RelationNotFoundError

class MyCharm(ops.CharmBase):
    def __init__(self, framework):
        super().__init__(framework)
        framework.observe(self.on.update_status, self._on_update_status)

    def _on_update_status(self, event):
        try:
            self.model._backend.relation_get(1, 'unit/0', False)
        except ModelError as e:
            if 'permission denied' in str(e).lower():
                raise RelationNotFoundError('relation 1')


captured = {}

class MyProxyCharm(ops.CharmBase):
    def __init__(self, framework):
        super().__init__(framework)
        framework.observe(self.on.update_status, self._on_update_status)

    def _on_update_status(self, event):
        try:
            self.model._backend.relation_get(1, 'unit/0', False)
        except ModelError as e:
            captured['error'] = e


def test_relation_get_raises_relation_not_found():
    ctx = testing.Context(MyCharm, meta={'name': 'my-charm'})
    with pytest.raises(RelationNotFoundError):
        ctx.run(ctx.on.update_status(), testing.State())


def test_relation_get_raises_model_error():
    ctx = testing.Context(MyProxyCharm, meta={'name': 'my-proxy-charm'})
    ctx.run(ctx.on.update_status(), testing.State())
    assert isinstance(captured['error'], ModelError)
    assert 'permission denied' in str(captured['error']).lower()

